// Tests for WorkflowApp — the federated entry exposed as "workflow/WorkflowApp".
//
// The platform-chrome surface used by WorkflowLayout is stubbed so routing
// tests don't pull in the full Topbar / WebSocket machinery (which would
// crash the jsdom worker). Only the chrome HOOK surface is mocked;
// paraglide/messages stays real so route content imports its translated
// strings normally.
//
// Task 6 (#1314) replaced the standalone /workflows landing hero with the
// Canvas / Templates / Projects nav shell — /workflows now redirects to
// /workflows/canvas rather than rendering a dedicated landing surface.
// Tab-level behavior (aria-selected, keyboard nav, direct deep-links) is
// covered by tests/WorkflowNavShell.test.tsx; this file covers the
// app-level redirect/fallback routing that sits above the nav shell.
//
// MemoryRouter carries basename="/workflows" — see WorkflowNavShell.test.tsx
// for why this matches the real router frame WorkflowApp always mounts in.

import { render, screen, waitFor } from "@testing-library/react";
import { MemoryRouter } from "react-router-dom";
import { vi } from "vitest";

vi.mock("@omnicore-platform/platform-chrome", async () => {
  const actual = await vi.importActual<
    typeof import("@omnicore-platform/platform-chrome")
  >("@omnicore-platform/platform-chrome");
  return {
    ...actual,
    Topbar: () => null,
    useTheme: () => ({ theme: "light", setTheme: () => undefined }),
    useLocale: () => "en-US",
    useWorkspaceList: () => ({
      workspaces: [],
      refetch: async () => undefined,
    }),
  };
});

import WorkflowApp from "../src/WorkflowApp";

import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

test("redirects /workflows to the Canvas tab content", () => {
  render(
    <MemoryRouter basename="/workflows" initialEntries={["/workflows"]}>
      <WorkflowApp />
    </MemoryRouter>,
  );
  expect(
    screen.getByRole("heading", { name: m.workflow_canvas_empty_title() }),
  ).toBeInTheDocument();
  expect(
    screen.getByRole("link", { name: m.workflow_nav_canvas() }),
  ).toHaveAttribute("aria-current", "page");
});

test("falls back to the Canvas tab for an unknown workflow path", () => {
  render(
    <MemoryRouter
      basename="/workflows"
      initialEntries={["/workflows/does-not-exist-yet"]}
    >
      <WorkflowApp />
    </MemoryRouter>,
  );
  expect(
    screen.getByRole("heading", { name: m.workflow_canvas_empty_title() }),
  ).toBeInTheDocument();
});

test("mounts the shared platform chrome shell around the nav tabs", async () => {
  render(
    <MemoryRouter basename="/workflows" initialEntries={["/workflows/templates"]}>
      <WorkflowApp />
    </MemoryRouter>,
  );
  expect(screen.getByTestId("workflow-main")).toBeInTheDocument();
  // The Templates tab is the real library since #1345, so its heading only
  // appears once the (msw-stubbed) list request resolves.
  await waitFor(() =>
    expect(
      screen.getByRole("heading", { name: m.workflow_templates_title() }),
    ).toBeInTheDocument(),
  );
});


--- frontends/workflow-mfe/tests/WorkflowLayout.test.tsx (206 lines) ---
// Tests for WorkflowLayout — the persistent chrome wrapping every workflow route.
//
// The existing WorkflowApp test stubs Topbar as () => null, so the layout's
// callback props (onSwitchWorkspace success/error, onProfile,
// onAccountSettings, onSignOut) never fire and stay uncovered. This suite
// renders a Topbar stub that DOES invoke those props, plus mocks
// switchWorkspace / WorkspaceApiError to drive the success + not-accessible
// error branches of handleSwitchWorkspace.

import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter } from "react-router-dom";
import { afterEach, beforeEach, expect, test, vi } from "vitest";

// ── Mocks ───────────────────────────────────────────────────────────────────

// Hoisted so the vi.mock factories (themselves hoisted above all imports) can
// reference these without a TDZ error. WorkspaceApiError must be a real class
// so the layout's `instanceof` check matches.
// Button labels for the Topbar stub. Kept as constants (not JSX-literal text)
// to satisfy react/jsx-no-literals, and hoisted so the mock factory sees them.
const {
  navigateMock,
  switchWorkspaceMock,
  refetchWorkspacesMock,
  logoutMock,
  FakeWorkspaceApiError,
  BTN,
} = vi.hoisted(() => {
  class FakeWorkspaceApiError extends Error {
    constructor(
      public readonly code: string,
      message: string,
    ) {
      super(message);
      this.name = "WorkspaceApiError";
    }
  }
  return {
    navigateMock: vi.fn(),
    switchWorkspaceMock: vi.fn(),
    refetchWorkspacesMock: vi.fn(async () => undefined),
    logoutMock: vi.fn(),
    FakeWorkspaceApiError,
    BTN: {
      switch: "switch-workspace",
      profile: "open-profile",
      account: "open-account",
      signOut: "sign-out",
    },
  };
});

// react-router-dom: keep the real exports but pin useNavigate so we can assert
// the profile / account-settings navigation targets.
vi.mock("react-router-dom", async () => {
  const actual =
    await vi.importActual<typeof import("react-router-dom")>(
      "react-router-dom",
    );
  return { ...actual, useNavigate: () => navigateMock };
});

vi.mock("../src/lib/logout", () => ({ logout: logoutMock }));

// platform-chrome: stub the hooks + a Topbar that surfaces the layout's
// callback props as clickable buttons so they actually fire.
interface StubTopbarProps {
  onSignOut: () => void;
  onProfile: () => void;
  onAccountSettings: () => void;
  onSwitchWorkspace: (orgId: string) => void;
}

vi.mock("@omnicore-platform/platform-chrome", async () => {
  const actual = await vi.importActual<
    typeof import("@omnicore-platform/platform-chrome")
  >("@omnicore-platform/platform-chrome");
  return {
    ...actual,
    Topbar: (props: StubTopbarProps) => (
      <div>
        <button onClick={() => props.onSwitchWorkspace("org-2")}>
          {BTN.switch}
        </button>
        <button onClick={props.onProfile}>{BTN.profile}</button>
        <button onClick={props.onAccountSettings}>{BTN.account}</button>
        <button onClick={props.onSignOut}>{BTN.signOut}</button>
      </div>
    ),
    useTheme: () => ({ theme: "light", setTheme: () => undefined }),
    useLocale: () => "en-US",
    useWorkspaceList: () => ({
      workspaces: [],
      refetch: refetchWorkspacesMock,
    }),
    switchWorkspace: switchWorkspaceMock,
    WorkspaceApiError: FakeWorkspaceApiError,
  };
});

import { WorkflowLayout } from "../src/layout/WorkflowLayout";

// ── Harness ───────────────────────────────────────────────────────────────────

function renderLayout(): void {
  render(
    <MemoryRouter initialEntries={["/workflows"]}>
      <WorkflowLayout />
    </MemoryRouter>,
  );
}

let reloadMock: ReturnType<typeof vi.fn>;

beforeEach(() => {
  navigateMock.mockReset();
  switchWorkspaceMock.mockReset();
  refetchWorkspacesMock.mockClear();
  logoutMock.mockReset();
  // Replace window.location with a stub that preserves origin/href (MSW needs
  // origin to resolve the relative /api/v1/session URL) but makes reload a spy
  // (jsdom's real reload is non-configurable / a no-op).
  reloadMock = vi.fn();
  const { origin, href } = window.location;
  Object.defineProperty(window, "location", {
    configurable: true,
    value: { origin, href, reload: reloadMock },
  });
});

afterEach(() => {
  vi.restoreAllMocks();
});

// The Topbar only mounts once useSession resolves; wait for it each test.
async function waitForChrome(): Promise<void> {
  await waitFor(() =>
    expect(screen.getByText("switch-workspace")).toBeInTheDocument(),
  );
}

test("renders the main region with the Topbar chrome once the session loads", async () => {
  renderLayout();
  await waitForChrome();
  expect(screen.getByTestId("workflow-main")).toBeInTheDocument();
});

test("reloads the page after a successful workspace switch", async () => {
  switchWorkspaceMock.mockResolvedValue(undefined);
  renderLayout();
  await waitForChrome();

  await userEvent.click(screen.getByText("switch-workspace"));

  await waitFor(() => expect(switchWorkspaceMock).toHaveBeenCalledWith("org-2"));
  await waitFor(() => expect(reloadMock).toHaveBeenCalledTimes(1));
});

test("refetches workspaces when the switch fails with workspace_not_accessible", async () => {
  switchWorkspaceMock.mockRejectedValue(
    new FakeWorkspaceApiError("workspace_not_accessible", "no access"),
  );
  renderLayout();
  await waitForChrome();

  await userEvent.click(screen.getByText("switch-workspace"));

  await waitFor(() => expect(refetchWorkspacesMock).toHaveBeenCalledTimes(1));
  expect(reloadMock).not.toHaveBeenCalled();
});

test("swallows an unrelated switch error without refetching or reloading", async () => {
  switchWorkspaceMock.mockRejectedValue(new Error("network down"));
  renderLayout();
  await waitForChrome();

  await userEvent.click(screen.getByText("switch-workspace"));

  // Give the rejected promise a tick to settle.
  await waitFor(() => expect(switchWorkspaceMock).toHaveBeenCalled());
  expect(refetchWorkspacesMock).not.toHaveBeenCalled();
  expect(reloadMock).not.toHaveBeenCalled();
});

test("navigates to /profile from the Topbar profile action", async () => {
  renderLayout();
  await waitForChrome();
  await userEvent.click(screen.getByText("open-profile"));
  expect(navigateMock).toHaveBeenCalledWith("/profile");
});

test("navigates to /account from the Topbar account-settings action", async () => {
  renderLayout();
  await waitForChrome();
  await userEvent.click(screen.getByText("open-account"));
  expect(navigateMock).toHaveBeenCalledWith("/account");
});

test("invokes logout from the Topbar sign-out action", async () => {
  renderLayout();
  await waitForChrome();
  await userEvent.click(screen.getByText("sign-out"));
  expect(logoutMock).toHaveBeenCalledTimes(1);
});


--- frontends/workflow-mfe/tests/WorkflowNavShell.test.tsx (339 lines) ---
// Tests for WorkflowNavShell — the top-level Canvas / Templates / Projects
// NAVIGATION (#1314) plus the three URL-synced placeholder routes it drives.
//
// These used to be assertions about `role="tab"` / `aria-selected`. They are
// not any more, because the shell is not a tablist: every "tab" changes the
// ROUTE, so it is a <nav> of real <Link>s and the state signal is
// `aria-current="page"`. Asserting `href` is not decoration here — it is the
// regression cover for the whole reason the widget changed shape:
// middle-click, cmd-click and "Open in new tab" are dead without one, and the
// button-shaped version had none.
//
// The platform-chrome surface used by WorkflowLayout is stubbed exactly as in
// WorkflowApp.test.tsx so routing tests don't pull in the full Topbar /
// WebSocket machinery. paraglide/messages stays real so tab labels + route
// placeholder copy render their translated strings normally.
//
// THERE ARE TWO ROUTER FRAMES, AND THEY ARE NOT EQUIVALENT. This file used to
// claim they were, and that claim is what let a broken nav shell ship:
//
//   * Standalone (frontends/workflow-mfe/src/main.tsx) mounts
//     <BrowserRouter basename="/workflows">. A basename IS stripped from
//     useLocation().pathname, so the app sees "/templates".
//   * Federated (shell-mfe/src/App.tsx) mounts WorkflowApp at a SPLAT route,
//     path="/workflows/*", with NO basename. A splat match does not strip
//     anything — the app sees the full "/workflows/templates".
//
// Only the federated frame is what a real user hits. `renderAt` keeps the
// standalone frame covered; `renderFederatedAt` adds the one that matters,
// and every navigation assertion below is exercised in BOTH.

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { MemoryRouter, Route, Routes, useLocation } from "react-router-dom";
import { vi } from "vitest";

vi.mock("@omnicore-platform/platform-chrome", async () => {
  const actual = await vi.importActual<
    typeof import("@omnicore-platform/platform-chrome")
  >("@omnicore-platform/platform-chrome");
  return {
    ...actual,
    Topbar: () => null,
    useTheme: () => ({ theme: "light", setTheme: () => undefined }),
    useLocale: () => "en-US",
    useWorkspaceList: () => ({
      workspaces: [],
      refetch: async () => undefined,
    }),
  };
});

import { type ReactElement } from "react";
import WorkflowApp from "../src/WorkflowApp";
import { tabIdFromPath } from "../src/layout/WorkflowNavShell";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

/** The STANDALONE frame: basename strips the prefix before the app sees it. */
function renderAt(path: string): void {
  render(
    <MemoryRouter basename="/workflows" initialEntries={[path]}>
      <WorkflowApp />
    </MemoryRouter>,
  );
}

/**
 * The FEDERATED frame — byte-for-byte what shell-mfe does: a splat route at
 * "/workflows/*" and no basename, so the pathname reaching WorkflowApp still
 * carries "/workflows". This is the frame every real user is in.
 */
function renderFederatedAt(path: string): void {
  render(
    <MemoryRouter initialEntries={[path]}>
      <Routes>
        <Route path="/workflows/*" element={<WorkflowApp />} />
      </Routes>
      <LocationProbe />
    </MemoryRouter>,
  );
}

/** Renders the current pathname so a test can assert where navigate() landed. */
function LocationProbe(): ReactElement {
  const { pathname } = useLocation();
  return <div data-testid="pathname">{pathname}</div>;
}

test("redirects /workflows to /workflows/canvas with the Canvas link current", () => {
  renderAt("/workflows");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_canvas() }),
  ).toHaveAttribute("aria-current", "page");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_templates() }),
  ).not.toHaveAttribute("aria-current");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_projects() }),
  ).not.toHaveAttribute("aria-current");
});

test("clicking the Templates link makes it current and updates the URL", async () => {
  const user = userEvent.setup();
  renderAt("/workflows");

  await user.click(screen.getByRole("link", { name: m.workflow_nav_templates() }));

  expect(
    screen.getByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveAttribute("aria-current", "page");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_canvas() }),
  ).not.toHaveAttribute("aria-current");
});

test("direct navigation to /workflows/projects makes the Projects link current", () => {
  renderAt("/workflows/projects");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_projects() }),
  ).toHaveAttribute("aria-current", "page");
});

test("direct navigation to /workflows/canvas makes the Canvas link current", () => {
  renderAt("/workflows/canvas");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_canvas() }),
  ).toHaveAttribute("aria-current", "page");
});

test("every destination is a real href, so middle-click and cmd-click work", () => {
  // The whole reason this stopped being a tablist. A `role="tab"` button
  // carries no href, so "Open in new tab" / "Copy link address" / a
  // middle-click are all silently dead on it.
  renderAt("/workflows/canvas");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_canvas() }),
  ).toHaveAttribute("href", "/workflows/canvas");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveAttribute("href", "/workflows/templates");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_projects() }),
  ).toHaveAttribute("href", "/workflows/projects");
});

test("the nav has an accessible name and every link is in the tab order", async () => {
  // A nav is NOT a composite widget, so it has no roving tabindex: all three
  // destinations are individually reachable with Tab, which is exactly the
  // opposite of the tablist contract this replaced.
  const user = userEvent.setup();
  renderAt("/workflows/canvas");

  expect(screen.getByRole("navigation")).toHaveAccessibleName();

  await user.tab();
  expect(screen.getByRole("link", { name: m.workflow_nav_canvas() })).toHaveFocus();
  await user.tab();
  expect(
    screen.getByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveFocus();
  await user.tab();
  expect(
    screen.getByRole("link", { name: m.workflow_nav_projects() }),
  ).toHaveFocus();
});

test("Enter on a focused link navigates to it", async () => {
  const user = userEvent.setup();
  renderAt("/workflows/canvas");

  screen.getByRole("link", { name: m.workflow_nav_templates() }).focus();
  await user.keyboard("{Enter}");

  expect(
    screen.getByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveAttribute("aria-current", "page");
});

test("an unrelated keypress does not change the current link", async () => {
  const user = userEvent.setup();
  renderAt("/workflows/canvas");

  screen.getByRole("link", { name: m.workflow_nav_canvas() }).focus();
  await user.keyboard("{Escape}");

  expect(
    screen.getByRole("link", { name: m.workflow_nav_canvas() }),
  ).toHaveAttribute("aria-current", "page");
});


// ---------------------------------------------------------------------------
// The federated frame (shell-mfe) — the one real users get.
// ---------------------------------------------------------------------------
//
// shell-mfe mounts this app as `<Route path="/workflows/*">` (see
// frontends/shell-mfe/src/App.tsx) — an ordinary splat route, which creates NO
// basename. That is a materially different router frame from the standalone
// bootstrap above: with a basename React Router strips the prefix from
// `location.pathname` and re-adds it on `navigate`, and with a splat it does
// neither. The suite above only ever exercised the basename frame, which is
// why a nav shell that works standalone and is broken under federation stayed
// green. Every assertion here is regression cover for that.

test("federated: the link matching the URL is the current one, not Canvas", async () => {
  // The reported symptom: deep-linking to /workflows/templates rendered the
  // right route but left CANVAS highlighted, because the active tab was
  // derived with pathname.startsWith("/templates") — true only once a
  // basename has stripped the prefix.
  renderFederatedAt("/workflows/templates");

  expect(
    await screen.findByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveAttribute("aria-current", "page");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_canvas() }),
  ).not.toHaveAttribute("aria-current");
});

test("federated: /workflows/projects marks Projects current", async () => {
  renderFederatedAt("/workflows/projects");

  expect(
    await screen.findByRole("link", { name: m.workflow_nav_projects() }),
  ).toHaveAttribute("aria-current", "page");
});

test("federated: every href stays inside the /workflows subtree", async () => {
  // The relative-vs-absolute half of the original report, now assertable
  // DIRECTLY rather than only through a click: an absolute target would
  // render href="/templates" and leave the subtree the host routes.
  renderFederatedAt("/workflows/canvas");

  expect(
    await screen.findByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveAttribute("href", "/workflows/templates");
  expect(
    screen.getByRole("link", { name: m.workflow_nav_projects() }),
  ).toHaveAttribute("href", "/workflows/projects");
});

test("federated: clicking a link actually navigates under the /workflows prefix", async () => {
  // The other half of the report: clicking "Templates" did nothing useful,
  // because the target was ABSOLUTE — it left the /workflows subtree entirely
  // and landed on a path the host has no route for. The pathname probe is what
  // pins that down; the aria-current assertion alone would also pass if the
  // link merely re-rendered in place.
  const user = userEvent.setup();
  renderFederatedAt("/workflows/canvas");

  await user.click(screen.getByRole("link", { name: m.workflow_nav_templates() }));

  expect(screen.getByTestId("pathname")).toHaveTextContent(
    "/workflows/templates",
  );
  expect(
    await screen.findByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveAttribute("aria-current", "page");
  // And the outlet really swapped — the templates route owns this heading.
  expect(
    await screen.findByRole("heading", { name: m.workflow_templates_title() }),
  ).toBeInTheDocument();
});

test("federated: clicking through to Projects and back to Canvas works", async () => {
  const user = userEvent.setup();
  renderFederatedAt("/workflows/canvas");

  await user.click(screen.getByRole("link", { name: m.workflow_nav_projects() }));
  expect(screen.getByTestId("pathname")).toHaveTextContent(
    "/workflows/projects",
  );
  expect(
    await screen.findByRole("link", { name: m.workflow_nav_projects() }),
  ).toHaveAttribute("aria-current", "page");

  await user.click(screen.getByRole("link", { name: m.workflow_nav_canvas() }));
  expect(screen.getByTestId("pathname")).toHaveTextContent("/workflows/canvas");
  expect(
    await screen.findByRole("link", { name: m.workflow_nav_canvas() }),
  ).toHaveAttribute("aria-current", "page");
});

test("federated: keyboard activation navigates within the /workflows subtree", async () => {
  const user = userEvent.setup();
  renderFederatedAt("/workflows/canvas");

  screen.getByRole("link", { name: m.workflow_nav_templates() }).focus();
  await user.keyboard("{Enter}");

  expect(screen.getByTestId("pathname")).toHaveTextContent(
    "/workflows/templates",
  );
  expect(
    await screen.findByRole("link", { name: m.workflow_nav_templates() }),
  ).toHaveAttribute("aria-current", "page");
});

test("federated: /workflows redirects to the Canvas link", async () => {
  renderFederatedAt("/workflows");

  expect(
    await screen.findByRole("link", { name: m.workflow_nav_canvas() }),
  ).toHaveAttribute("aria-current", "page");
});

// ---------------------------------------------------------------------------
// tabIdFromPath
// ---------------------------------------------------------------------------
//
// Unit-tested directly rather than only through a rendered route: it has to
// answer for the standalone frame (where the basename is already stripped) and
// for nested pathnames, and a rendered assertion cannot distinguish "reports
// Canvas because the tab logic is wrong" from "reports Canvas because the
// catch-all redirected there".

test.each([
  // [pathname, tab]
  ["/workflows/canvas", "canvas"],
  ["/workflows/templates", "templates"],
  ["/workflows/projects", "projects"],
  // Federated, bare mount mid-redirect — no tab segment yet.
  ["/workflows", "canvas"],
  // Standalone: the basename is already stripped.
  ["/canvas", "canvas"],
  ["/projects", "projects"],
  ["/", "canvas"],
  // A nested route keeps its parent tab — the shape #1353 introduces. A
  // last-segment match would report Canvas for both of these.
  ["/workflows/projects/1e5d3c62-0000-4000-8000-000000000000", "projects"],
  ["/workflows/projects/1e5d3c62-0000-4000-8000-000000000000/settings", "projects"],
  ["/projects/1e5d3c62-0000-4000-8000-000000000000", "projects"],
  // Trailing slashes must not create an empty segment.
  ["/workflows/projects/", "projects"],
  // An unknown child of the mount is Canvas, matching WorkflowApp's catch-all.
  ["/workflows/nope", "canvas"],
])("tabIdFromPath(%s) -> %s", (pathname, tab) => {
  expect(tabIdFromPath(pathname)).toBe(tab);
});


--- frontends/workflow-mfe/tests/logout.test.ts (37 lines) ---
// Tests for logout() — the full-navigation sign-out helper.
//
// logout() sets window.location.href to the shell-bff logout endpoint, which
// clears the session cookie then 302s to Keycloak end_session. We can't follow
// the redirect in jsdom, so we assert the navigation target is set.

import { afterEach, beforeEach, expect, test, vi } from "vitest";
import { logout } from "../src/lib/logout";

let hrefValue = "";

beforeEach(() => {
  hrefValue = "";
  // jsdom's window.location.href is not writable by default; redefine it so
  // logout()'s assignment is observable.
  Object.defineProperty(window, "location", {
    configurable: true,
    value: {
      get href() {
        return hrefValue;
      },
      set href(v: string) {
        hrefValue = v;
      },
    },
  });
});

afterEach(() => {
  vi.restoreAllMocks();
});

test("navigates the browser to the shell-bff logout endpoint", () => {
  logout();
  expect(hrefValue).toBe("/api/v1/auth/logout");
});


