import { MemoryRouter } from "react-router-dom";
import { afterEach, beforeEach, expect, test, vi } from "vitest";

// ── Mocks ───────────────────────────────────────────────────────────────────

// Hoisted so the vi.mock factories (themselves hoisted above all imports) can
// reference these without a TDZ error. WorkspaceApiError must be a real class
// so the layout's `instanceof` check matches.
// Button labels for the Topbar stub. Kept as constants (not JSX-literal text)
// to satisfy react/jsx-no-literals, and hoisted so the mock factory sees them.
const {
  navigateMock,
  switchWorkspaceMock,
  refetchWorkspacesMock,
  logoutMock,
  FakeWorkspaceApiError,
  BTN,
} = vi.hoisted(() => {
  class FakeWorkspaceApiError extends Error {
    constructor(
      public readonly code: string,
      message: string,
    ) {
      super(message);
      this.name = "WorkspaceApiError";
    }
  }
  return {
    navigateMock: vi.fn(),
    switchWorkspaceMock: vi.fn(),
    refetchWorkspacesMock: vi.fn(async () => undefined),
    logoutMock: vi.fn(),
    FakeWorkspaceApiError,
    BTN: {
      switch: "switch-workspace",
      profile: "open-profile",
      account: "open-account",
      signOut: "sign-out",
    },
  };
});

// react-router-dom: keep the real exports but pin useNavigate so we can assert
// the profile / account-settings navigation targets.
vi.mock("react-router-dom", async () => {
  const actual =
    await vi.importActual<typeof import("react-router-dom")>(
      "react-router-dom",
    );
  return { ...actual, useNavigate: () => navigateMock };
});

vi.mock("../src/lib/logout", () => ({ logout: logoutMock }));

// platform-chrome: stub the hooks + a Topbar that surfaces the layout's
// callback props as clickable buttons so they actually fire.
interface StubTopbarProps {
  onSignOut: () => void;
  onProfile: () => void;
  onAccountSettings: () => void;
  onSwitchWorkspace: (orgId: string) => void;
}

vi.mock("@omnicore-platform/platform-chrome", async () => {
  const actual = await vi.importActual<
    typeof import("@omnicore-platform/platform-chrome")
  >("@omnicore-platform/platform-chrome");
  return {
    ...actual,
    Topbar: (props: StubTopbarProps) => (
      <div>
        <button onClick={() => props.onSwitchWorkspace("org-2")}>
          {BTN.switch}
        </button>
        <button onClick={props.onProfile}>{BTN.profile}</button>
        <button onClick={props.onAccountSettings}>{BTN.account}</button>
        <button onClick={props.onSignOut}>{BTN.signOut}</button>
