/**
 * Regression guard — no bare in-workflow navigation links.
 *
 * workflow-mfe is mounted by shell-mfe at `/workflows/*`. Any in-app
 * navigation must therefore carry the `/workflows` prefix: a
 * `to="/workspace/…"` or `navigate("/workspace/…")` literal that omits
 * `/workflows` resolves at the shell root and bounces the user out of
 * Workflows (the range-mfe `/range`-prefix lesson).
 *
 * This is a SOURCE-SCAN test. It reads every src file at compile time via
 * Vite's `import.meta.glob({ query: '?raw', eager: true })` — NOT node:fs —
 * because workflow-mfe has no @types/node, so importing the node builtins would
 * break `tsc -b` (a CI gate). `import.meta.glob` is typed by `vite/client`
 * and runs in the jsdom/vitest worker.
 *
 * Route `path=` props stay UNPREFIXED (the parent /workflows/* match
 * supplies the prefix); only `to=` / `navigate(` call sites are in-app
 * navigation. The guard fires on a navigation literal whose path begins
 * with `/workflows` but is actually a bare workspace path — for the
 * scaffolding we only have the landing route, so the guard's job is to
 * stay green as routes are added.
 *
 * The regex matches a `to=`/`navigate(` target that is an ABSOLUTE path NOT
 * beginning with `/workflows` (and not an `/api/` fetch URL, which never
 * appears in `to=`/`navigate(`). Correctly-prefixed links read
 * `to="/workflows/…"`.
 */
import { describe, expect, it } from "vitest";

const SOURCE_FILES = import.meta.glob("/src/**/*.{ts,tsx}", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;

// Matches a navigation call site whose target is an absolute path that does
// NOT start with `/workflows` (e.g. to="/workspace/…", navigate("/runs/…")).
// `to="/workflows/…"` has `workflows` directly after the quote, so it never
// matches.
const BARE_NAV_LINK =
  /(?:to=|navigate\()\s*\{?\s*[`'"]\/(?!workflows[/`'"]|profile|account)[a-z]/;

describe("workflow-mfe in-app navigation links", () => {
  it("never navigates to a bare path missing the /workflows prefix", () => {
    const offenders: string[] = [];

    for (const [path, source] of Object.entries(SOURCE_FILES)) {
      source.split("\n").forEach((line, i) => {
        if (BARE_NAV_LINK.test(line)) {
          offenders.push(`${path}:${i + 1}: ${line.trim()}`);
        }
      });
    }

    expect(
      offenders,
      `Found in-workflow navigation links missing the /workflows prefix:\n${offenders.join(
        "\n",
      )}`,
    ).toEqual([]);
  });

  it("scans a non-empty set of source files (guards against a broken glob)", () => {
    expect(Object.keys(SOURCE_FILES).length).toBeGreaterThan(0);
  });
});


