// Tests for useSession — fetches /api/v1/session and unwraps the {data,error}
// envelope into a flat Session, with a module-level cache.
//
// fetchSession holds module-level `cached` / `inFlight` singletons, so each
// test re-imports the hook fresh (vi.resetModules) to isolate cache state.
// MSW (tests/setup.ts) backs the happy path; per-test server.use(...) drives
// the error branch.

import { renderHook, waitFor } from "@testing-library/react";
import { http, HttpResponse } from "msw";
import { afterEach, beforeEach, expect, test, vi } from "vitest";
import { server } from "./setup";

beforeEach(() => {
  vi.resetModules();
});

afterEach(() => {
  server.resetHandlers();
});

async function loadHook() {
  // Fresh module → fresh `cached`/`inFlight` singletons per test.
  const mod = await import("../src/lib/useSession");
  return mod.useSession;
}

test("resolves to the ready state with the unwrapped session", async () => {
  const useSession = await loadHook();
  const { result } = renderHook(() => useSession());

  await waitFor(() => expect(result.current.state).toBe("ready"));
  if (result.current.state !== "ready") throw new Error("expected ready");
  expect(result.current.session.email).toBe("alice@example.com");
  expect(result.current.session.org_id).toBe("org-1");
});

test("surfaces the server-provided error message on a non-ok response", async () => {
  server.use(
    http.get("/api/v1/session", () =>
      HttpResponse.json({ error: "session_expired" }, { status: 401 }),
    ),
  );
  const useSession = await loadHook();
  const { result } = renderHook(() => useSession());

  await waitFor(() => expect(result.current.state).toBe("error"));
  if (result.current.state !== "error") throw new Error("expected error");
  expect(result.current.message).toBe("session_expired");
});

test("falls back to an HTTP-status message when the body has no error", async () => {
  server.use(
    http.get("/api/v1/session", () =>
      HttpResponse.json({}, { status: 503 }),
    ),
  );
  const useSession = await loadHook();
  const { result } = renderHook(() => useSession());

  await waitFor(() => expect(result.current.state).toBe("error"));
  if (result.current.state !== "error") throw new Error("expected error");
  expect(result.current.message).toBe("HTTP 503");
});

test("falls back to a generic message when the rejection is not an Error", async () => {
  // fetchSession's .catch coerces a non-Error rejection (no .message) to the
  // generic "Session error". A rejected fetch normally throws a TypeError, so
  // we stub fetch to reject with a bare string to exercise the false branch.
  const fetchSpy = vi
    .spyOn(globalThis, "fetch")
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    .mockRejectedValue("boom" as any);
  const useSession = await loadHook();
  const { result } = renderHook(() => useSession());

  await waitFor(() => expect(result.current.state).toBe("error"));
  if (result.current.state !== "error") throw new Error("expected error");
  expect(result.current.message).toBe("Session error");
  fetchSpy.mockRestore();
});

test("shares the in-flight promise across concurrent mounts (no double fetch)", async () => {
  const fetchSpy = vi.spyOn(globalThis, "fetch");
  const useSession = await loadHook();

  // Two mounts before the first resolves — the second hits the `inFlight`
  // branch and reuses the same promise rather than issuing a second request.
  const a = renderHook(() => useSession());
  const b = renderHook(() => useSession());

  await waitFor(() => expect(a.result.current.state).toBe("ready"));
  await waitFor(() => expect(b.result.current.state).toBe("ready"));
  expect(fetchSpy).toHaveBeenCalledTimes(1);
  fetchSpy.mockRestore();
});

test("serves the cached session without re-fetching on a second mount", async () => {
  const useSession = await loadHook();

  // Prime the cache with a first successful mount.
  const first = renderHook(() => useSession());
  await waitFor(() => expect(first.result.current.state).toBe("ready"));

  // Now make the endpoint fail. A second mount that hits the cache must NOT
  // re-fetch — it returns the cached session and stays ready.
  server.use(
    http.get("/api/v1/session", () =>
      HttpResponse.json({ error: "should_not_be_called" }, { status: 500 }),
    ),
  );

  const second = renderHook(() => useSession());
  await waitFor(() => expect(second.result.current.state).toBe("ready"));
  if (second.result.current.state !== "ready") throw new Error("expected ready");
  expect(second.result.current.session.email).toBe("alice@example.com");
});



